  if(new Set(input.lines.map(line=>line.itemId)).size!==input.lines.length)throw new Error("Each product can appear only once in a stock increase.");
  const rows=input.lines.map(line=>{found(w.items,line.itemId,"Product");const value=money(D(line.quantity).mul(line.cost));if(D(value).lte(0))throw new Error("Each added stock line must have a positive value.");return {...line,value};});
  result=id();
  for(const row of rows)move(w,row.itemId,input.warehouseId,money(row.quantity),row.value,result,input.date,"adjustment");
  const total=money(sum(rows.map(row=>row.value)));
